 const q=boards.planning,plan=q.add('plan',60,70,'exploration'),fleet=q.add('fleet',480,100);q.add('plan',60,450,'research');const origin=q.add('coordinate',-280,70),destination=q.add('coordinate',870,100);origin.outputs[0].coordinate='[270,510]';destination.outputs[0].coordinate='[450,220]';q.connect(origin.id,origin.outputs[0].id,plan.id,plan.inputs[0].id);q.connect(fleet.id,fleet.outputs[0].id,destination.id,destination.outputs[0].id);
