// Independent planning documents. Runtime ship location is not operator/planning data.
(()=>{
const E=NodeEditors,M=E.model,ed=E.editors.planning,key='pelagic-planning-layers-v13';
let layers=[{id:'plan-1',name:'출정 계획 1',board:ed.board}],active='plan-1',sequence=1,lastSaved='',searchTarget=null;
const strip=document.createElement('div');strip.className='planning-layers';strip.setAttribute('aria-label','계획 레이어');ed.root.prepend(strip);
const picker=document.createElement('dialog');picker.id='coordinatePicker';document.body.append(picker);
const output=document.createElement('dialog');output.id='planFormat';document.body.append(output);
function snapshot(){return{version:1,active,sequence,layers:layers.map(l=>({id:l.id,name:l.name,board:{nodes:l.board.nodes,edges:l.board.edges,groups:l.board.groups,view:l.board.view,lineMode:l.board.lineMode}}))};}
function save(){const data=JSON.stringify(snapshot());if(data===lastSaved)return;try{localStorage.setItem(key,data);lastSaved=data;}catch{toast('계획 레이어를 저장하지 못했습니다.');}}
function decode(raw){if(!raw||!Array.isArray(raw.nodes)||raw.nodes.length>100||!Array.isArray(raw.edges)||raw.edges.length>400)throw Error('잘못된 레이어');const b=new M.Board('planning'),ids=new Map(),ports=new Map();for(const old of raw.nodes){if(!['coordinate','plan','fleet'].includes(old.type)||ids.has(old.id)||!Number.isFinite(old.x)||!Number.isFinite(old.y))throw Error('잘못된 노드');const n=M.createNode(old.type,old.x,old.y,old.subtype),id=n.id;Object.assign(n,old);n.id=id;n.location='[270,510]';n.status='대기중';n.travel=0;delete n.travelTarget;ids.set(old.id,id);for(const side of ['inputs','outputs']){if(!Array.isArray(old[side])||old[side].length>24)throw Error('잘못된 포트');n[side]=old[side].map(p=>{const fresh=M.createNode('coordinate',0,0).outputs[0];ports.set(p.id,fresh.id);return{id:fresh.id,kind:'plan',...(old.type==='coordinate'?{coordinate:p.coordinate??old.coordinate??'',siteId:p.siteId}:{})};});}b.nodes.push(n);}b.normalizePlanning();for(const e of raw.edges){if(b.node(ids.get(e.from))?.subtype==='exploration')continue;const r=b.connect(ids.get(e.from),ports.get(e.out),ids.get(e.to),ports.get(e.in),e.toSide);if(!r.ok)throw Error(r.error);}b.groups=(raw.groups||[]).filter(g=>['x','y','w','h'].every(k=>Number.isFinite(g[k])));if(raw.view&&['x','y','scale'].every(k=>Number.isFinite(raw.view[k])))b.view={...raw.view,scale:Math.max(.25,Math.min(1.8,raw.view.scale))};b.lineMode=raw.lineMode==='straight'?'straight':'curve';b.recompute();return b;}
try{const data=JSON.parse(localStorage.getItem(key)||'null');if(data?.version===1&&Array.isArray(data.layers)&&data.layers.length&&data.layers.length<=30){if(data.layers.some(l=>l.board?.nodes?.some(n=>n.type==='coordinate'&&n.inputs?.length))&&!localStorage.getItem(key+'-before-v19'))localStorage.setItem(key+'-before-v19',JSON.stringify(data));const restored=data.layers.map(l=>({id:String(l.id),name:String(l.name).slice(0,50),board:decode(l.board)}));layers=restored;active=layers.some(l=>l.id===data.active)?data.active:layers[0].id;sequence=Math.max(data.sequence||1,layers.length);}}catch{toast('계획 레이어 복원 실패 · 기존 기본 계획을 유지합니다.');}
function tabs(){strip.innerHTML=layers.map(l=>'<span class="planning-layer-tab" role="tab" tabindex="0" aria-selected="'+(l.id===active)+'" data-plan-layer="'+esc(l.id)+'" title="클릭: 계획 레이어 전환"><button aria-label="레이어 이름 편집" data-layer-edit="'+esc(l.id)+'">✎</button><span data-layer-name="'+esc(l.id)+'">'+esc(l.name)+'</span> <small>'+l.board.nodes.length+' nodes</small> <span role="button" tabindex="0" aria-label="레이어 삭제" data-layer-delete="'+esc(l.id)+'">×</span></span>').join('')+'<button data-plan-new aria-label="계획 레이어 추가">＋ 새 레이어</button>';}
function activate(id){const l=layers.find(v=>v.id===id);if(!l)return;const old=layers.find(v=>v.id===active);if(old)old.board=ed.board;active=id;ed.board=l.board;E.boards.planning=l.board;E.render('planning');tabs();save();}
strip.addEventListener('click',e=>{e.stopPropagation();const del=e.target.closest('[data-layer-delete]')?.dataset.layerDelete;if(del){const l=layers.find(l=>l.id===del);if(!confirm(l.name+' 레이어와 모든 내용을 삭제할까요?'))return;layers=layers.filter(l=>l.id!==del);if(!layers.length){const id='plan-'+(++sequence);layers.push({id,name:'출정 계획 '+sequence,board:new M.Board('planning')});}if(active===del){active=layers[0].id;ed.board=layers[0].board;E.boards.planning=ed.board;E.render('planning');}tabs();save();return;}if(e.target.closest('[data-layer-input]'))return;const rename=e.target.closest('[data-layer-edit]')?.dataset.layerEdit;if(rename){editName(rename);return;}if(e.target.closest('[data-plan-new]')){const id='plan-'+(++sequence);layers.push({id,name:'출정 계획 '+sequence,board:new M.Board('planning')});activate(id);}const id=e.target.closest('[data-plan-layer]')?.dataset.planLayer;if(id)activate(id);});
strip.addEventListener('keydown',e=>{if(e.target.matches('[data-layer-delete],[data-plan-layer]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.click();}});
function editName(id){const l=layers.find(v=>v.id===id),label=strip.querySelector('[data-layer-name="'+id+'"]');if(!l||!label)return;const input=document.createElement('input');input.dataset.layerInput=id;input.value=l.name;input.maxLength=50;input.setAttribute('aria-label','레이어 이름');label.replaceWith(input);let done=false;function finish(cancel=false){if(done)return;done=true;if(!cancel&&input.value.trim())l.name=input.value.trim();tabs();save();}input.addEventListener('blur',()=>finish());input.addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Enter'||e.key==='Escape'){e.preventDefault();finish(e.key==='Escape');}});input.focus();input.select();}

function candidates(){return [...nodes.map(n=>({id:n.id,name:n.name,x:n.x,y:n.y,type:n.purity?'자원':'거점'})),{id:'contact-07',name:'미확인 위협 / CONTACT',x:840,y:195,type:'위협 · 예시 접촉'}];}
function results(){const q=picker.querySelector('input').value.trim().toLowerCase();picker.querySelector('.coordinate-results').innerHTML=candidates().filter(n=>(n.name+n.type+'['+n.x+','+n.y+']').toLowerCase().includes(q)).map(n=>'<button data-pick-coordinate="'+esc(n.id)+'"><strong>'+esc(n.name)+'</strong><span>'+esc(n.type)+' · ['+n.x+','+n.y+']</span></button>').join('')||'<p>일치하는 좌표가 없습니다.</p>';}
function search(board,n,portId){searchTarget={board,id:n.id,portId:portId||n.outputs[0]?.id};picker.innerHTML='<form method="dialog"><h2>해역 좌표 검색</h2><button class="dialog-close" value="close" aria-label="닫기">×</button></form><input aria-label="거점 또는 위협 검색" placeholder="거점 이름, 자원, 위협 또는 좌표 검색"><div class="coordinate-results"></div><small>현재 해역 거점과 지도에 표시된 예시 위협을 조회합니다.</small>';picker.querySelector('input').addEventListener('input',results);results();picker.showModal();picker.querySelector('input').focus();}
picker.addEventListener('click',e=>{const id=e.target.closest('[data-pick-coordinate]')?.dataset.pickCoordinate;if(!id)return;const c=candidates().find(n=>n.id===id),n=searchTarget?.board.node(searchTarget.id);if(c&&n){const port=n.outputs.find(p=>p.id===searchTarget.portId);if(!port)return;port.coordinate='['+c.x+','+c.y+']';port.siteId=c.id;searchTarget.board.recompute();if(searchTarget.board===ed.board)E.render('planning');save();}picker.close();});
function compile(board,n){board.recompute();const route=(n.coordinateBindings||[]).filter(v=>v.destination).map(v=>({nodeId:v.nodeId,portId:v.portId,coordinate:v.coordinate}));if(!route.length||route.some(r=>!/^\[\d{1,4},\d{1,4}\]$/.test(r.coordinate)||r.coordinate.slice(1,-1).split(',').some((v,i)=>Number(v)>(i?1520:2000)))){toast('출력에 목적지 좌표를 연결하세요.');return;}const origins=[],seen=new Set();function upstream(id){if(seen.has(id))return;seen.add(id);for(const e of board.edges.filter(e=>e.to===id&&!e.error)){const source=board.node(e.from);if(e.toSide==='outputs')continue;if(source?.type==='coordinate'){const p=source.outputs.find(p=>p.id===e.out);if(p?.coordinate)origins.push(p.coordinate);}upstream(e.from);}}upstream(n.id);const format={schemaVersion:1,kind:'fleet_movement_plan',layerId:active,templateId:n.id,title:n.title,originCoordinates:origins,route,ships:n.ships.map(r=>({type:r.type,requested:r.count})),autoFill:!!n.autoFill,status:'draft'};const json=JSON.stringify(format,null,2);try{localStorage.setItem('pelagic-command-format-v13',json);}catch{toast('양식 저장 실패 · JSON을 복사해 보관하세요.');}output.innerHTML='<form method="dialog"><h2>출정 명령 양식</h2><button class="dialog-close" value="close" aria-label="닫기">×</button></form><p>DB 전달용 초안 · 생성만으로 함대가 이동하지 않습니다.</p><textarea readonly aria-label="명령 JSON"></textarea><button data-format-download>JSON 다운로드</button>';output.querySelector('textarea').value=json;output.querySelector('[data-format-download]').onclick=()=>{const url=URL.createObjectURL(new Blob([json],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='fleet-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};output.showModal();return format;}
// Save/load toolbar commands apply only to the open layer; the collection is autosaved separately.
ed.root.addEventListener('click',()=>{const l=layers.find(v=>v.id===active);if(l)l.board=ed.board;tabs();save();});
setInterval(()=>{const l=layers.find(v=>v.id===active);if(l)l.board=ed.board;save();},1000);
window.PlanningUI={search,compile,activate,save,get layers(){return layers;},get active(){return active;}};
// Do not replace the restored board with the initial board when opening the first document.
ed.board=layers.find(l=>l.id===active).board;E.boards.planning=ed.board;E.render('planning');tabs();
})();
